import 'beat_grid.dart';

/// A beat that ships with the app. Its grid is known exactly, so no analysis
/// is needed and it doubles as the reference for testing sync.
class BundledBeat {
  const BundledBeat({
    required this.id,
    required this.title,
    required this.asset,
    required this.grid,
    required this.bars,
  });

  final String id;
  final String title;
  final String asset;
  final BeatGrid grid;
  final int bars;

  Duration get loopLength =>
      grid.timeOfBeat((bars * grid.beatsPerBar).toDouble()) -
      grid.downbeatOffset;
}

/// Generated by tool/make_practice_beat.py.
const practice90 = BundledBeat(
  id: 'practice_90',
  title: 'Practice beat, 90 BPM',
  asset: 'assets/beats/practice_90.wav',
  grid: BeatGrid(bpm: 90),
  bars: 16,
);

const bundledBeats = [practice90];
